/// Reads and queries sparse posting lists from a blockfile keyed by
/// `(prefix, u32)` with [`SparsePostingBlock`] values.
///
/// Layout:
/// - Data blocks: prefix = `encode_u32(dim)`, key = block index `0, 1, …`.
/// - Directory parts (only for dimensions with >1 data block): prefix =
///   `DIRECTORY_PREFIX + encode_u32(dim)`, key = part index `0, 1, …`.
#[derive(Clone)]
pub struct MaxScoreReader<'me> {
    posting_reader: BlockfileReader<'me, u32, SparsePostingBlock>,
}

impl<'me> MaxScoreReader<'me> {
    pub fn new(posting_reader: BlockfileReader<'me, u32, SparsePostingBlock>) -> Self {
        Self { posting_reader }
    }

    /// An identifier suitable for forking the underlying blockfile writer.
    pub fn posting_id(&self) -> Uuid {
        self.posting_reader.id()
    }

    pub fn posting_reader(&self) -> &BlockfileReader<'me, u32, SparsePostingBlock> {
        &self.posting_reader
    }

    /// All data posting blocks for the given encoded dimension key, in
    /// ascending block-index order.
    pub async fn get_posting_blocks(
        &self,
        encoded_dim: &str,
    ) -> Result<Vec<SparsePostingBlock>, MaxScoreError> {
        Ok(self
            .posting_reader
            .get_prefix(encoded_dim)
            .await?
            .map(|(_, block)| block)
            .collect())
    }

    /// The per-dimension directory (present only for dimensions that span
    /// more than one data block), paired with the number of on-disk parts
    /// it was stored in. Returns `None` when no directory is stored.
    pub async fn get_directory(
        &self,
        encoded_dim: &str,
    ) -> Result<Option<(Directory, usize)>, MaxScoreError> {
        let directory_prefix = format!("{}{}", DIRECTORY_PREFIX, encoded_dim);
        let mut parts = Vec::new();
        for (_, block) in self.posting_reader.get_prefix(&directory_prefix).await? {
            match DirectoryBlock::from_block(block) {
                Ok(part) => parts.push(part),
                // Not a directory block — should never happen for this prefix.
                Err(_) => continue,
            }
        }
        if parts.is_empty() {
            return Ok(None);
        }
        let part_count = parts.len();
        let directory = Directory::from_parts(parts)?;
        Ok(Some((directory, part_count)))
    }

    /// The list of dimension IDs stored in the index (empty for an empty
    /// index), in ascending order.
    pub async fn get_all_dimension_ids(&self) -> Result<Vec<u32>, MaxScoreError> {
        let mut dims = BTreeSet::new();
        for (prefix, _, _) in self.posting_reader.get_range(.., ..).await? {
            // Directory parts live under the DIRECTORY_PREFIX namespace.
            if prefix.starts_with(DIRECTORY_PREFIX) {
                continue;
            }
            if let Ok(dim) = decode_u32(prefix) {
                dims.insert(dim);
            }
        }
        Ok(dims.into_iter().collect())
    }

    /// Top-k sparse dot-product query. Returns up to `k` results sorted by
    /// score descending (ties broken by ascending offset). Respects the
    /// `mask`: `Include` restricts to offsets in the bitmap, `Exclude`
    /// omits offsets in the bitmap.
    pub async fn query(
        &self,
        query: impl IntoIterator<Item = (u32, f32)>,
        k: u32,
        mask: SignedRoaringBitmap,
    ) -> Result<Vec<Score>, MaxScoreError> {
        if k == 0 {
            return Ok(Vec::new());
        }

        // Accumulate the full dot product for every candidate document that
        // passes the mask. Exhaustive scoring guarantees perfect recall
        // (subject only to f16 weight quantization).
        let mut scores: BTreeMap<u32, f32> = BTreeMap::new();
        for (dim, query_weight) in query {
            let encoded = encode_u32(dim);
            let blocks = self.get_posting_blocks(&encoded).await?;
            if blocks.is_empty() {
                continue;
            }
            let cursor = PostingCursor::from_blocks(blocks);
            for &(offset, weight) in cursor.entries() {
                if mask.contains(offset) {
                    *scores.entry(offset).or_insert(0.0) += weight * query_weight;
                }
            }
        }

        if scores.is_empty() {
            return Ok(Vec::new());
        }

        // Keep the top-k via a min-heap keyed on (score, offset).
        let k = k as usize;
        let mut heap: BinaryHeap<Score> = BinaryHeap::with_capacity(k + 1);
        for (offset, score) in scores {
            heap.push(Score { score, offset });
            if heap.len() > k {
                heap.pop();
            }
        }

        let mut results = heap.into_vec();
        // `Score` orders as a min-heap (reversed); sort descending by score,
        // then ascending by offset for deterministic tie-breaking.
        results.sort_by(|a, b| {
            b.score
                .total_cmp(&a.score)
                .then(a.offset.cmp(&b.offset))
        });
        Ok(results)
    }
}

