/// Returned by [`MaxScoreWriter::commit`]. Exposes the posting blockfile id
/// and the flush operation.
pub struct MaxScoreFlusher {
    posting_flusher: BlockfileFlusher,
}

impl MaxScoreFlusher {
    pub fn id(&self) -> Uuid {
        self.posting_flusher.id()
    }

    pub async fn flush(self) -> Result<(), MaxScoreError> {
        self.posting_flusher
            .flush::<u32, SparsePostingBlock>()
            .await?;
        Ok(())
    }
}

/// A single mutation emitted to the blockfile at commit time.
enum WriteOp {
    Set(SparsePostingBlock),
    Delete,
}

/// Writes sparse posting lists into a blockfile. Supports fresh builds and
/// incremental forks from an existing [`MaxScoreReader`].
///
/// All writes are buffered in `delta` (dimension -> offset -> add/delete)
/// until [`commit`](Self::commit).
#[derive(Clone)]
pub struct MaxScoreWriter<'me> {
    posting_writer: BlockfileWriter,
    old_reader: Option<MaxScoreReader<'me>>,
    block_size: usize,
    // dimension_id -> (offset -> Some(weight) for upsert, None for delete)
    delta: Arc<DashMap<u32, DashMap<u32, Option<f32>>>>,
}

